def legendre_symbol(a, p):
    """Compute Legendre symbol (a/p)"""
    if a % p == 0:
        return 0
    return 1 if pow(a, (p-1)//2, p) == 1 else -1

n = 23
# Construct sequence b: b[0] = 1, b[i] = (i/23) for i=1..22
b = [1]  # b_0 = 1
for i in range(1, n):
    b.append(legendre_symbol(i, n))

print("b:", b)
print("sum b:", sum(b))

# Check autocorrelation
def autocorr(seq, k):
    n = len(seq)
    return sum(seq[i] * seq[(i+k) % n] for i in range(n))

print("\nAutocorrelations:")
for k in range(1, n):
    ak = autocorr(b, k)
    print(f"k={k}: A_b(k)={ak}")
